//! Embeds the licensed HugeIcons Pro masks into the executable when they exist at build time.
//!
//! `assets/icons/hugeicons/` and `assets/icons/hugeicons_bulk/` are git-ignored (generated by
//! `tools/setup-hugeicons.sh`, which CI runs with the maintainer's key). When present they are
//! packed into one compressed blob and `cfg(embedded_hugeicons)` is set; otherwise nothing
//! happens and the app uses the bundled icons.

#[path = "src/icon_pack.rs"]
mod icon_pack;

use std::{env, fs, path::Path};

fn main() {
    println!("cargo::rustc-check-cfg=cfg(embedded_hugeicons)");
    println!("cargo::rerun-if-changed=build.rs");
    println!("cargo::rerun-if-changed=src/icon_pack.rs");
    let root = Path::new(&env::var_os("CARGO_MANIFEST_DIR").unwrap()).join("assets/icons");
    let mut entries = Vec::new();
    for set in ["hugeicons", "hugeicons_bulk"] {
        let dir = root.join(set);
        println!("cargo::rerun-if-changed={}", dir.display());
        let Ok(rd) = fs::read_dir(&dir) else { continue };
        let mut files: Vec<_> = rd.flatten().map(|e| e.path()).collect();
        files.sort();
        for path in files {
            if path.extension().is_none_or(|x| x != "a8") {
                continue;
            }
            let stem = path.file_stem().unwrap().to_string_lossy().into_owned();
            entries.push((format!("{set}/{stem}"), fs::read(&path).unwrap()));
        }
    }
    if entries.is_empty() {
        return;
    }
    let out = Path::new(&env::var_os("OUT_DIR").unwrap()).join("hugeicons.pack");
    fs::write(&out, icon_pack::pack(&entries)).unwrap();
    println!("cargo::rustc-cfg=embedded_hugeicons");
}
